import{_ as i,C as p,o as s,c as r,j as t,a,E as c,ag as l}from"./chunks/framework.DUTPmUpA.js";const d="/_assets/ts_example.B_1BDcnE.mp4",n="data:image/png;base64,",u="/_assets/cloneRepo.n-ougjvW.png",h="/_assets/clickAddressBar.BLhat74c.png",f=JSON.parse('{"title":"Машинопись Введение","description":"","frontmatter":{"title":"Машинопись Введение","author":"Shush","steamId":76561197994333650,"date":"07.03.2021"},"headers":[],"relativePath":"scripting/Typescript/typescript-introduction.md","filePath":"scripting/Typescript/typescript-introduction.md"}'),m={name:"scripting/Typescript/typescript-introduction.md"};function y(g,e,A,b,T,k){const o=p("StaticVideo");return s(),r("div",null,[e[0]||(e[0]=t("hr",null,null,-1)),e[1]||(e[1]=t("h1",{id:"машинопись-введение",tabindex:"-1"},[a("Машинопись Введение "),t("a",{class:"header-anchor",href:"#машинопись-введение","aria-label":'Permalink to "Машинопись Введение"'},"​")],-1)),e[2]||(e[2]=t("p",null,"Typescript — это мощный инструмент, который мы можем использовать, чтобы улучшить нашу способность правильно писать сценарии для файлов Dota 2. Используя tstl (Typescript-to-Lua), он автоматически генерирует файл Lua для игры, который будет использоваться для каждого файла, над которым вы работаете — этот процесс полностью автоматический с момента его запуска.",-1)),e[3]||(e[3]=t("p",null,[a("Typescript более строгий по сравнению с Lua, будет использовать типы для реализации определенных функций и немедленно предупредит вас, если вы сделаете что-то, что не имеет для него смысла, и будет показывать ошибку, пока вы ее не исправите. Например, выполнение "),t("code",null,"GetStrength()"),a(" для способности не имеет смысла и приведет к появлению сообщения об ошибке.")],-1)),e[4]||(e[4]=t("p",null,[a("Typescript может хорошо работать с большинством редакторов, использующих плагины, однако рекомендуется использовать "),t("a",{href:"https://code.visualstudio.com/",target:"_blank",rel:"noreferrer"},"VSCode"),a(", поскольку он имеет встроенную поддержку Typescript и является очень мощным редактором.")],-1)),c(o,{path:d,controls:"true"}),e[5]||(e[5]=l('<h2 id="плюсы-и-минусы-использования-typescript" tabindex="-1">Плюсы и минусы использования Typescript <a class="header-anchor" href="#плюсы-и-минусы-использования-typescript" aria-label="Permalink to &quot;Плюсы и минусы использования Typescript&quot;">​</a></h2><p><strong>Плюсы:</strong></p><ul><li>Обеспечивает соблюдение типов, предотвращает использование ненужных функций. — Typescript гораздо больше похож на большинство языков, таких как C#, Java, Javascript и C (по сравнению с Lua).</li><li>Автозаполнение, при котором отображаются только функции API, соответствующие вызываемому типу.</li><li>Экономит массу времени за счет немедленного обнаружения логических ошибок в коде, вместо того, чтобы искать их в игре (иногда в крайних случаях, которые не могут быть обнаружены во время локального тестирования).</li><li>Потрясающая поддержка машинописного текста в Интернете (например, Stack Overflow) для решения распространенных вопросов по машинописному тексту.</li><li>Сам Typescript имеет очень мощные встроенные функции и типы, такие как наборы, карты и функции массивов. Кроме того, он поддерживает наследование классов и типов. — Typescript используется как для Lua, так и для Javascript, поэтому вам никогда не придется переключаться между языками сценариев; Typescript преобразует его на нужный вам язык. — Автозаполнение различных аргументов в API, например встроенного списка событий.</li><li>Встроенные перечисления и интерфейсы, позволяющие чрезвычайно быстро и легко найти определенное значение на основе Dota.</li><li>Очень легко обновлять новые API, когда Valve (со временем) выпустит новые функции.</li><li>Создает символическую ссылку на вашу папку Dota 2 в рамках установки, поэтому вы можете легко интегрировать свои изменения в GitHub, если захотите.</li></ul><p><strong>Минусы:</strong></p><ul><li>Первая настройка занимает некоторое время.</li><li>Некоторые редкие типы могут быть неправильными. При необходимости их можно обновить вручную.</li><li>Иногда требуется дополнительная настройка для конкретной игровой логики, такой как интерфейсы, типы и приведения типов (это опять-таки связано с природой типизированного языка).</li><li>Не очень удобно интегрировать в текущие проекты, хотя все равно может работать.</li><li>Ссылаться на код или руководства, написанные на Lua, в Typescript может быть непросто из-за различий в работе этих языков.</li></ul><h2 id="настроика-typescript" tabindex="-1">Настройка TypeScript <a class="header-anchor" href="#настроика-typescript" aria-label="Permalink to &quot;Настройка TypeScript&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Это руководство предполагает, что вы используете Windows. Если у вас другая операционная система, обратитесь к нам в разделе TypeScript в <a href="https://t.me/+4wTdvuzBPzUxOTgy" target="_blank" rel="noreferrer">Telegram-канале</a>.</p></div><p>First, since Typescript uses Node.js, it must be installed on your computer. You can download NodeJS from <a href="https://nodejs.org/en/" target="_blank" rel="noreferrer">here</a>. Simply choose the recommended version, which is the latest stable version. Download and install it with its default configuration.</p><p>Next, navigate to the <a href="https://github.com/ModDota/TypeScriptAddonTemplate" target="_blank" rel="noreferrer">Typescript template</a>. This template has most of the files of a new addon configured for you, along with Typescript support. There are two versions to use the template:</p><ol><li><p>Without GitHub: if you&#39;re not planning to put your code in GitHub, clone the above template. See below for explanation how.</p></li><li><p>С GitHub: если вы планируете разместить свой код на GitHub, нажмите кнопку <img src="'+n+'" alt="Use this template">, расположенную в правом верхнем углу страницы github. Это создаст новый репозиторий GitHub, который будет использовать шаблон под вашим именем. Введите имя и описание репозитория, а также укажите, является ли он общедоступным или частным. Вы можете оставить флажок «Включить все ветки» снятым, а затем нажать «Создать репозиторий на основе шаблона». Когда новый репозиторий будет создан, клонируйте его. См. ниже объяснение того, как это сделать. Тем, кто не знаком с github, я рекомендую использовать графический интерфейс Github, например <a href="https://desktop.github.com/" target="_blank" rel="noreferrer">Github Desktop</a>.</p></li></ol><p>Клонирование репозитория означает создание его копии на вашем компьютере. Это можно сделать, нажав «Код», затем «Загрузить Zip», как показано здесь:</p><p><img src="'+u+'" alt="Cloning from Github"></p><p>Затем вы можете извлечь ZIP-архив куда угодно. Однако НЕ помещайте его в папку Dota 2. Например, я поместил его на свой рабочий стол в папку «Пользовательские игры Dota 2». Извлеченная папка называется <code>TypeScriptAddonTemplate-master</code>, поэтому просто переименуйте ее, чтобы более правильно отразить название вашей пользовательской игры. Для этого урока я назвал его <code>typescript-example</code>.</p><h2 id="создание-аддона-на-основе-typescript-в-dota" tabindex="-1">Создание аддона на основе Typescript в Dota <a class="header-anchor" href="#создание-аддона-на-основе-typescript-в-dota" aria-label="Permalink to &quot;Создание аддона на основе Typescript в Dota&quot;">​</a></h2><p>Теперь, когда у нас есть файлы на нашем компьютере, мы можем очень быстро настроить новую аддонную игру. Прежде чем это сделать, осталось сделать несколько шагов:</p><ul><li>Зайдите в свою папку, в моем случае <code>typescript-example</code>.</li><li>Откройте <code>package.json</code> в любом текстовом редакторе. Вы заметите, что поле <code>name</code> представляет собой пустую строку. Добавьте название своей пользовательской игры. Например, я назвал его <code>typescript_tutorial</code>. Поле должно выглядеть так:</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;name&quot;: &quot;typescript_tutorial&quot;,</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Сохраните и закройте файл.</p><p>:::информация Убедитесь, что внутри папки <code>game/dota_addons</code> и <code>content/dota_addons</code> папки с игрой Dota 2 нет папки с таким именем. В процессе установки эти папки будут созданы для вас. Если папки существуют, сначала удалите их или измените имя в <code>package.json</code> на другое. :::</p><ul><li>Находясь в папке с файлом <code>package.json</code>, который вы только что отредактировали, щелкните адресную строку, чтобы путь к вашей папке стал выделенным и доступным для редактирования в виде текста. Это должно выглядеть так:</li></ul><p><img src="'+h+'" alt="Click on path"></p><ul><li><p>Пока путь выделен, удалите текст и вместо этого введите «cmd» и нажмите Enter. Откроется командная оболочка с путем к папке, показанным прямо перед курсором ввода.</p></li><li><p>Введите <code>npm install</code> и нажмите Enter. Вы увидите полосу загрузки, заполнение которой может занять около минуты. Если все прошло успешно, вы увидите, что рядом с папками <code>game</code> и <code>content</code> теперь есть значок «ярлыка». Теперь они связаны с вашей папкой Dota 2. Папка <code>typescript_tutorial</code> теперь существует как для <code>game/dota_addons/</code>, так и для <code>content/dota_addons</code> в вашей папке Dota 2.</p></li></ul><p>:::информация Папки с символическими ссылками представляют собой копии друг друга, где любое действие, выполненное с одной папкой, также применяется к другой папке. Поэтому вы можете просто работать с удобно расположенной папкой (в моем примере <code>Desktop/Dota 2 custom games/typescript-example</code>), и она автоматически применится и к папке Steam Dota 2. :::</p><h2 id="структура-дополнения-typescript" tabindex="-1">Структура дополнения Typescript <a class="header-anchor" href="#структура-дополнения-typescript" aria-label="Permalink to &quot;Структура дополнения Typescript&quot;">​</a></h2><p>Большая часть структуры Typescript идентична стандартному дополнению Dota, например, папка <code>scripts/npc/</code>. Обратите внимание на папку <code>src</code> в корне проекта. Здесь вы создаете файлы Typescript и работаете над ними. При компиляции полученные файлы Lua помещаются в соответствующие места, например <code>/game/scripts/vscripts/</code> для файлов, созданных из <code>/src/vscripts/</code>. Вы можете добавить дополнительные папки внутри этих папок, что сохранит ту же маршрутизацию в выходном месте.</p><p>Вы можете изменить структуру папок внутри аддона. Однако вам может потребоваться настроить пути вывода в соответствии с этими изменениями. Некоторые изменения могут нарушить работу мода, поскольку Dota ожидает установки определенной структуры (например, <code>game/scripts/vscripts</code>).</p><p>:::информация В <code>src</code> вы также найдете папку <code>common</code>. Эта папка чрезвычайно полезна для хранения объявлений интерфейса, которые используются игровой логикой и панорамой, таких как события и сетевые таблицы, а также других пользовательских объявлений, таких как перечисления. <strong>Эта папка должна содержать только файлы d.ts</strong>. :::</p><p>Существует несколько дополнительных файлов и папок, отвечающих за идентификацию Typescript и работу с API Dota 2, а также в пользовательской игре в целом. Большую часть этих файлов можно оставить нетронутыми. Большинство этих файлов расположены в папке <code>/src/vscripts/</code>:</p><ul><li><p><code>tsconfig.json</code>: настраивает работу Typescript в Lua-части проекта. Файл того же типа существует в папке <code>/src/panorama/</code> для конфигурации JavaScript для панорамы.</p></li><li><p><code>vscripts/lib/dota_ts_adapter.ts</code>: отвечает за регистрацию различных распространенных классов, таких как способности, предметы и модификаторы.</p></li><li><p><code>vscripts/lib/tstl-utils.ts</code>: отвечает за перевод машинописного текста в Lua.</p></li><li><p><code>vscripts/lib/timers.lua</code> и <code>vscripts/lib/timers.d.ts</code>: общая библиотека таймеров уже включена по умолчанию в ее форму Lua, а timers.d.ts включает интерфейс, позволяющий использовать библиотеку таймеров в Typescript.</p></li></ul><h2 id="обновление-вашего-аддона" tabindex="-1">Обновление вашего аддона <a class="header-anchor" href="#обновление-вашего-аддона" aria-label="Permalink to &quot;Обновление вашего аддона&quot;">​</a></h2><p>Время от времени Valve выпускает новый API или изменения в существующем API, обычно во время мероприятий и крупных патчей. Ваш проект Typescript не будет автоматически адаптироваться к этим изменениям, поскольку их сначала необходимо сохранить и напечатать, что обычно делает сообщество, поддерживающее шаблон Typescript. Однако когда будет объявлено о новом обновлении Typescript для Dota 2, вы сможете легко обновить свой проект. Есть два способа сделать это:</p><ul><li><p>Использование терминала VSCode: если вы выбрали редактор VSCode и в нем загружена папка вашего проекта, нажмите «Терминал» -&gt; «Новый терминал». Откроется новый терминал. Введите <code>npm update</code> и нажмите Enter.</p></li><li><p>Использование cmd: откройте cmd из корневого каталога вашего проекта (в моем примере <code>Desktop/Dota 2 custom games/typescript-example</code>), затем введите <code>npm update</code> и нажмите Enter. Проект автоматически обновится до последней версии.</p></li></ul><h2 id="активация-наблюдателя" tabindex="-1">Активация Наблюдателя <a class="header-anchor" href="#активация-наблюдателя" aria-label="Permalink to &quot;Активация Наблюдателя&quot;">​</a></h2><p>Чтобы ваши файлы могли скомпилироваться и иметь скомпилированные эквиваленты Lua или javascript, необходимо активировать наблюдатель. Наблюдатель отслеживает все изменения, внесенные в ваши файлы в проекте, и немедленно создает эквивалент Lua или JavaScript, при условии, что файл скомпилирован без ошибок. Активировать наблюдателя можно тремя способами:</p><ul><li><p>Использование терминала VSCode: если вы используете VSCode и в нем загружена папка вашего проекта, нажмите «Терминал» -&gt; «Выполнить задачу сборки». Альтернативно вы можете использовать для этого горячую клавишу <code>Ctrl+Shift+B</code> по умолчанию.</p></li><li><p>Использование cmd: откройте cmd из корневого каталога вашего проекта (в моем примере <code>Desktop/Dota 2 custom games/typescript-example</code>), затем введите <code>npm run dev</code> и нажмите Enter.</p></li><li><p>Другие редакторы: в зависимости от редактора у него может быть собственный метод для вызова команды «Выполнить задачу сборки»; дополнительную информацию можно найти в документации редактора.</p></li></ul><h2 id="нормализованные-типы" tabindex="-1">Нормализованные типы <a class="header-anchor" href="#нормализованные-типы" aria-label="Permalink to &quot;Нормализованные типы&quot;">​</a></h2><p>При выгрузке перечислений из API Dota они имеют несколько предопределенных типов. С некоторыми из этих типов не очень удобно работать, поэтому вместо них мы используем нормализованные типы. Эти нормализованные типы слегка меняют перечисления, и их цель — повысить читаемость вашего кода. Шаблон поставляется с уже активированными нормализованными типами.</p><h2 id="интегрированные-примеры" tabindex="-1">Интегрированные примеры <a class="header-anchor" href="#интегрированные-примеры" aria-label="Permalink to &quot;Интегрированные примеры&quot;">​</a></h2><p>На момент написания этого руководства шаблон Typescript содержал несколько примеров, показывающих, как игровая логика реализуется в Typescript. Я рекомендую сохранить эти файлы для справки, пока вы не освоитесь с Typescript.</p><p>Примеры:</p><ul><li>В <code>src/vscripts/abilities/heroes/meepo/earthbind_ts_example.ts</code>: пример пользовательской способности Meepo Earthbind.</li><li>В <code>src/vscripts/modifiers/modifier_panic.ts</code>: специальный модификатор, который ограничивает команды и приказывает родителю периодически перемещаться в случайную позицию рядом с ним.</li><li>В <code>src/vscripts/GameMode.ts</code>: примеры логики игрового режима, такие как установка максимального количества игроков для каждой команды равным 3. Здесь также показаны примеры таймера и прослушивания событий.</li><li>В <code>src/panorama/hud.ts</code>: пример Panorama для подписки и отправки событий.</li></ul><p>Вы можете увидеть, как примеры применяются в вашем аддоне:</p><ul><li>К каждому выбранному вами герою будет добавлена специальная способность Meepo&#39;s Earthbind.</li><li>В центре экрана отображается панель приветствия. Нажатие на кнопку закрытия в нем удалит панель и применит модификатор паники на несколько секунд.</li></ul><h2 id="канал-typescript-в-telegram-moddotaru" tabindex="-1">Канал TypeScript в Telegram ModdotaRU <a class="header-anchor" href="#канал-typescript-в-telegram-moddotaru" aria-label="Permalink to &quot;Канал TypeScript в Telegram ModdotaRU&quot;">​</a></h2><p>У нас есть специальный раздел TypeScript в нашем <a href="https://t.me/+4wTdvuzBPzUxOTgy" target="_blank" rel="noreferrer">Telegram-канале ModdotaRU</a> для всех вопросов, связанных с TypeScript. Присоединяйтесь и задавайте вопросы — мы будем рады помочь.</p><h2 id="что-дальше" tabindex="-1">Что дальше? <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше?&quot;">​</a></h2><p>Ознакомьтесь с руководством по <a href="./typescript-ability">Abilities in Typescript</a>, в котором показано, как настроить и запрограммировать базовую возможность использования в игре.</p>',47))])}const S=i(m,[["render",y]]);export{f as __pageData,S as default};
